import subprocess,re
def run(inp):
    p=subprocess.run(['./VCtfTask'],cwd='/work',input=inp,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=5)
    return p.stdout.decode(errors='replace')
def parse(inp):
    o=run(inp)
    lines=o.splitlines()
    res={}
    for l in lines:
        m=re.match(r'\[(\d+)\] Input: \'(.*?)\', Power Level: \'(\d+)\'',l)
        if m:
            res[int(m.group(1))]={'inp':m.group(2),'pw':int(m.group(3))}
        m=re.match(r'\[(\d+)\] Before Temperature (\d+) => After Temperature (\d+)',l)
        if m:
            i=int(m.group(1)); res.setdefault(i,{})['before']=int(m.group(2)); res[i]['after']=int(m.group(3))
    flags=[l for l in lines if 'EMERGENCY' in l or 'TEST' in l]
    return res,flags
for inp in [b'123\n',b'123456789012345678901\n',b'12345678901234567890\n',b'\x00'*21+b'\n',b'\x7f'*21+b'\n']:
    r,f=parse(inp)
    print('INPUT',inp)
    for i in sorted(r): print(' ',i,r[i])
    print(' FLAGS',f)

