import subprocess,re
def parse(inp):
    p=subprocess.run(['./VCtfTask'],cwd='/work',input=inp,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,timeout=5)
    o=p.stdout.decode(errors='replace')
    res={}
    for l in o.splitlines():
        m=re.match(r'\[(\d+)\] Input: \'(.*?)\', Power Level: \'(\d+)\'',l)
        if m: res.setdefault(int(m.group(1)),{})['pw']=int(m.group(3))
        m=re.match(r'\[(\d+)\] Before Temperature (\d+) => After Temperature (\d+)',l)
        if m: res.setdefault(int(m.group(1)),{}).update(before=int(m.group(2)),after=int(m.group(3)))
    flags=[l for l in o.splitlines() if 'EMERGENCY' in l or 'TEST' in l]
    return res,flags
for v in ['000','001','002','010','050','099','100','101','111','123','150','199','200','201','222','250','255','256','257','300','400','500','600','700','800','900','999']:
    inp=(v*7+'\n').encode()
    r,f=parse(inp)
    pws=[r.get(i,{}).get('pw') for i in range(1,8)]
    aft=[r.get(i,{}).get('after') for i in range(1,8)]
    print(v,'pw=',pws,'after=',aft,'FLAG',f[-1])

