import re, sys

SRC = open('/challenge/CtfTask.v', 'r', errors='replace').read()

def norm(s):
    s = s.strip()
    if s.startswith('\\'):
        s = s[1:]
    return s.strip()

# ---------- parse module definitions ----------
moddefs = {}
for m in re.finditer(r'^module\s+(\S+)\s*\((.*?)\);(.*?)^endmodule', SRC, re.M | re.S):
    name = m.group(1)
    moddefs[name] = m.group(3)

# ---------- tiny verilog expression evaluator ----------
class P:
    def __init__(self, s, env):
        self.s = s
        self.i = 0
        self.env = env
    def ws(self):
        while self.i < len(self.s) and self.s[self.i].isspace():
            self.i += 1
    def peek(self):
        self.ws()
        return self.s[self.i] if self.i < len(self.s) else ''
    def parse(self):
        v = self.ternary()
        return v
    def ternary(self):
        c = self.orx()
        if self.peek() == '?':
            self.i += 1
            a = self.ternary()
            self.ws()
            assert self.s[self.i] == ':', (self.s, self.i)
            self.i += 1
            b = self.ternary()
            return a if c else b
        return c
    def orx(self):
        v = self.andx()
        while True:
            self.ws()
            if self.i < len(self.s) and self.s[self.i] == '|':
                self.i += 1
                w = self.andx()
                v = 1 if (v or w) else 0
            else:
                break
        return v
    def andx(self):
        v = self.unary()
        while True:
            self.ws()
            if self.i < len(self.s) and self.s[self.i] == '&':
                self.i += 1
                w = self.unary()
                v = 1 if (v and w) else 0
            else:
                break
        return v
    def unary(self):
        self.ws()
        if self.i < len(self.s) and self.s[self.i] == '~':
            self.i += 1
            return 0 if self.unary() else 1
        return self.primary()
    def primary(self):
        self.ws()
        if self.i >= len(self.s):
            raise ValueError('eof')
        c = self.s[self.i]
        if c == '(':
            self.i += 1
            v = self.ternary()
            self.ws()
            assert self.s[self.i] == ')'
            self.i += 1
            return v
        if c.isdigit():
            j = self.i
            while j < len(self.s) and (self.s[j].isalnum() or self.s[j] in "'_"):
                j += 1
            tok = self.s[self.i:j]
            self.i = j
            return parse_literal(tok)
        if c == "'":
            raise ValueError('unexpected tick ' + self.s)
        # identifier
        j = self.i
        while j < len(self.s) and (self.s[j].isalnum() or self.s[j] in '_[].\\$'):
            j += 1
        tok = self.s[self.i:j]
        self.i = j
        tok = norm(tok)
        if tok.startswith("1'h"):
            return int(tok[3:], 16) & 1
        if tok in self.env:
            return self.env[tok]
        raise KeyError('unknown ident %r in %r' % (tok, self.s))

def parse_literal(tok):
    t = tok.replace('_', '')
    if "'" in t:
        bits, val = t.split("'", 1)
        if val[0] == 'h':
            return int(val[1:], 16)
        if val[0] == 'b':
            return int(val[1:], 2)
        if val[0] == 'd':
            return int(val[1:])
        # size'value (no base) means binary?
        return int(val, 2)
    return int(t)

