lut6_tables = {}
for name, body in moddefs.items():
    if name.endswith('LUT6'):
        assigns = re.findall(r'assign\s+([^=]+?)\s*=\s*(.+?);', body, re.S)
        eqs = {}
        order = []
        for lhs, rhs in assigns:
            lhs = norm(lhs)
            eqs[lhs] = rhs
            order.append(lhs)
        # evaluate for all 64 input combos
        table = [0] * 64
        for idx in range(64):
            env = {}
            for k in range(6):
                env['I%d' % k] = (idx >> k) & 1
            # iterate to fixpoint
            for _ in range(8):
                changed = False
                for lhs in order:
                    v = P(eqs[lhs], env).parse()
                    if env.get(lhs) != v:
                        env[lhs] = v
                        changed = True
                if not changed:
                    break
            table[idx] = env.get('O', 0)
        lut6_tables[name] = table

# ---------- parse top module instances ----------
top = moddefs['CtfTask']
cells = []
lines = top.splitlines()
i = 0
inst_re = re.compile(r'^\s{2}(\S+)\s+(\S+)\s*\($')
while i < len(lines):
    m = inst_re.match(lines[i])
    if m:
        ctype = m.group(1)
        iname = m.group(2)
        j = i + 1
        block = []
        while j < len(lines) and ');' not in lines[j]:
            block.append(lines[j])
            j += 1
        if j < len(lines):
            block.append(lines[j])
        ports = {}
        for pl in block:
            for pm in re.finditer(r'\.(\w+)\s*\(\s*([^)]*?)\s*\)', pl):
                ports[pm.group(1)] = norm(pm.group(2))
        cells.append((ctype, iname, ports))
        i = j + 1
    else:
        i += 1

print('cells parsed', len(cells))
from collections import Counter
print(Counter(c[0].split('\\')[-1] for c in cells))
sys.stdout.flush()

