            elif base.startswith('LUT'):
                mm = re.search(r'LUT(\d+)', raw)
                n = int(mm.group(1))
                im = re.search(r"INIT=([0-9]+'[bh]?[0-9a-fA-F]+|[0-9]+)", raw)
                init = parse_literal(im.group(1)) if im else 0
                # build truth table
                tab = [(init >> i) & 1 for i in range(1<<n)]
                self.comb.append(('LUTn', (n, tab), ports))
            elif base.startswith('MUXCY'):
                self.comb.append(('MUXCY', None, ports))
            elif base.startswith('XORCY'):
                self.comb.append(('XORCY', None, ports))
            elif base.startswith('MUXF7') or base.startswith('MUXF8'):
                self.comb.append(('MUXF', None, ports))
            elif base.startswith('FDCE') or base.startswith('FDPE'):
                self.flops.append((base, norm(ports['Q']), ports['D'], ports.get('CLR'), ports.get('PRE'), ports.get('CE')))
            else:
                raise ValueError('unknown cell '+raw)
    def get(self, v):
        return lit_or_net(v, self.nets)
    def set(self, v, val):
        self.nets[norm(v)] = val & 1
    def eval_comb(self, inputs):
        # inputs dict name->value
        for k,v in inputs.items(): self.nets[k]=v&1
        for _ in range(100):
            changed=False
            for kind,par,ports in self.comb:
                def g(p): return self.get(ports.get(p,'1\'h0'))
                if kind=='LUT6':
                    idx = g('I0') | (g('I1')<<1) | (g('I2')<<2) | (g('I3')<<3) | (g('I4')<<4) | (g('I5')<<5)
                    o=par[idx]
                elif kind=='LUTn':
                    n,tab=par
                    idx=0
                    for k in range(n): idx |= g('I%d'%k)<<k
                    o=tab[idx]
                elif kind=='MUXCY':
                    o = g('CI') if g('S') else g('DI')
                elif kind=='XORCY':
                    o = g('CI') ^ g('LI')
                elif kind=='MUXF':
                    o = g('I1') if g('S') else g('I0')
                dst=norm(ports['O'])
                if self.nets.get(dst)!=o:
                    self.nets[dst]=o; changed=True
            if not changed: break
        return
    def tick(self, inputs):
        self.eval_comb(inputs)
        # compute D values now
        Ds=[]
        for base,q,d,clr,pre,ce in self.flops:
            Ds.append((base,q,self.get(d),clr,pre,ce))
        for base,q,d,clr,pre,ce in Ds:
            if clr and self.get(clr):
